package com.gomgomapps.math.core;
import java.util.*;
/** Public quotient/remainder for every nonnegative dividend and positive divisor within a bound. */
final class BoundedWholeDivision {
 static final String KIND="boundedWholeDivision";
 static boolean selected(String id,CurriculumLimits l){return id.equals("remainder")&&!l.hasWholeDigits()&&l.wholeMaximum(-1)>=10000&&l.wholeMaximum(-1)<=1000000&&l.givenMinimum(-1)==0;}
 static long count(int max){if(max<1||max>1000000)throw new IllegalArgumentException("division bound");return (max+1L)*max;}
 static int[] at(int max,long index){if(index<0||index>=count(max))throw new IndexOutOfBoundsException();return new int[]{(int)(index/max),1+(int)(index%max)};}
 static Question make(int a,int b){if(a<0||a>1000000||b<1||b>1000000)throw new IllegalArgumentException("division condition");Question q=new Question("remainder",a+" ÷ "+b,"",""+(a/b),""+(a%b));q.kind=KIND;q.labels=new String[]{"몫","나머지"};q.stepSupport=false;WholeDivisionRelations.attach(q);return q.withInputs(a,b);}
 static Question next(Random random,CurriculumLimits l,Map<String,Integer>recent){int max=l.wholeMaximum(-1),digits=1+random.nextInt(String.valueOf(max).length()),cap=(int)Math.min(max,Math.pow(10,digits)-1),a=random.nextInt(max+1),b=1+random.nextInt(cap);long start=(long)a*max+b-1,domain=count(max);for(int i=0;i<Math.max(256,recent.size()+1);i++){int[] v=at(max,(start+i)%domain);Question q=make(v[0],v[1]);if(l.allows(q)&&!recent.containsKey(q.signature()))return q;}throw new IllegalStateException("No fresh bounded division");}
 static Checker.Result check(Question q,List<String> answers){if(q.prompt==null||answers==null||answers.size()!=2)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");var m=java.util.regex.Pattern.compile("(0|[1-9][0-9]{0,6}) ÷ ([1-9][0-9]{0,6})").matcher(q.prompt);if(!m.matches())return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제 확인 필요");int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2));if(a>1000000||b>1000000)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제 확인 필요");int[] expected={a/b,a%b};for(int i=0;i<2;i++){if(answers.get(i)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"답 입력 필요");String input=Expression.normalize(answers.get(i).trim());if(input.length()>120||!input.matches("[+-]?[0-9]+(?:\\.[0-9]+)?(?:/[+-]?[0-9]+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수로 입력 필요");try{if(!Expression.number(input).equals(Rational.of(expected[i])))return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 답 확인");}catch(RuntimeException bad){return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수로 입력 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"정답");}
}
